func TestWithDialTimeoutKeepsPolicy(t *testing.T) {
	guard, err_1 := netguard.NewAllow([]string{"93.184.216.0/24"})
	if err_1 != nil {
		t.Fatalf("NewAllow failed: %v", err_1)
		return
	}
	slow := netguard.WithDialTimeout(guard, 5*time.Second)
	test.AssertFalse(t, netguard.Check(slow, "10.0.0.1"))
	test.AssertTrue(t, netguard.Check(slow, "93.184.216.34"))
}

func TestWithDialTimeoutDials(t *testing.T) {
	guard, err_2 := netguard.NewAllow([]string{"127.0.0.0/8"})
	if err_2 != nil {
		t.Fatalf("NewAllow failed: %v", err_2)
		return
	}
	slow := netguard.WithDialTimeout(guard, 2*time.Second)
	conn, dialErr := netguard.DialContext(slow, context.Background(), "tcp", "127.0.0.1:1")
	if dialErr == nil {
		_ = conn.Close()
	}
	msg := fmt.Sprintf("%v", dialErr)
	test.AssertFalse(t, kukistring.Contains(msg, "blocked by policy"))
}
